parameters.jsCode:
const brief = $json.output || $json;
const env = $('Envelope In').first().json;
const errors = [];

if (!brief.objective) errors.push('objective missing');
if (!brief.offer?.name) errors.push('offer.name missing');
if (!Array.isArray(brief.channels) || !brief.channels.length) errors.push('channels empty');

// A regulated claim forces the compliance profile up regardless of what the model chose.
const regulated = (brief.message?.key_claims || []).some(c => c.risk === 'regulated');
if (regulated) {
  brief.constraints = brief.constraints || {};
  if (brief.constraints.compliance_profile === 'none' || !brief.constraints.compliance_profile) {
    brief.constraints.compliance_profile = 'standard';
  }
}

return [{ json: {
  ...brief,
  brief_id: brief.brief_id || ('brf_' + env.trace_id.slice(0, 12)),
  tenant_id: env.tenant_id,
  brand_id: env.brand_id ?? null,
  vertical: env.vertical || 'generic',
  source: { channel: env.payload?.source_channel || 'api', raw_ref: env.payload?.raw_ref ?? null, received_at: new Date().toISOString() },
  confidence: typeof brief.confidence === 'number' ? brief.confidence : 0.5,
  _validation: { ok: errors.length === 0, errors, regulated_claims_present: regulated }
} }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "plan.brief.synthesize",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 4,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "plan.brief.synthesize", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

